CREATE ROLE authenticated; CREATE ROLE service_role; CREATE SCHEMA auth; CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$; CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql AS $$ SELECT nullif(current_setting('request.jwt.claim.role',true),'') $$; CREATE TYPE app_role AS ENUM('admin','user'); CREATE FUNCTION has_role(uuid,app_role) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;CREATE TABLE orders(arte_em_cards_code text,auction_id text,bundle_discount_cents bigint,buyer_received_at text,buyer_received_by text,carrier text,cep text,city text,complement text,coupon_code text,coupon_discount_cents bigint,cpf text,created_at timestamptz DEFAULT now(),discount_cents bigint,email text,event_added_by text,event_added_manually_at text,event_id uuid,event_previous text,finance_settled_at text,hand_delivery_fee_confirmed_at text,hand_delivery_fee_confirmed_by text,hand_delivery_fee_history jsonb,hand_delivery_fee_status text,id uuid PRIMARY KEY DEFAULT gen_random_uuid(),manual_adjustments jsonb,manual_created_at text,manual_created_by text,manual_created_by_email text,manual_source text,mercadopago_payment_id text,neighborhood text,notes text,number text,origin text,payment_method text,payment_note text,payment_paid_at text,phone text,pix_discount_cents bigint,pix_expires_at text,pix_qr_code text,pix_qr_code_base64 text,points_discount_cents bigint,points_earned bigint,points_redeemed bigint,pre_cancel_status text,recipient_name text,refunded_cents bigint,reschedule_required boolean,schedule_history jsonb,schedule_kind text,schedule_reopened_at text,scheduled_at timestamptz,shipping_cost_cents bigint,shipping_edit_history jsonb,shipping_edited_by_admin_at text,shipping_method text,state text,status text,stock_decremented boolean,stock_reservation_expires_at text,store_credit_cents bigint,street text,stripe_payment_intent text,stripe_session_id text,subtotal_cents bigint,superfrete_error text,superfrete_label_url text,superfrete_order_id text,superfrete_service_id text,superfrete_service_name text,superfrete_status text,total_cents bigint,tracking_code text,tracking_url text,updated_at timestamptz DEFAULT now(),user_id uuid,wallet_deduction_cents bigint);CREATE TABLE service_orders(amount_cents bigint,arte_em_cards_code text,carrier text,cep text,city text,code integer DEFAULT 1001,complement text,created_at timestamptz DEFAULT now(),edit_history jsonb,event_id uuid,fee_status text,id uuid PRIMARY KEY DEFAULT gen_random_uuid(),method text,neighborhood text,notes text,number text,payment_order_id text,phone text,recipient_name text,schedule_kind text,scheduled_at timestamptz,shipping_cost_cents bigint,stack_id uuid,state text,status text,street text,tracking_code text,tracking_url text,updated_at timestamptz DEFAULT now(),user_id uuid,whatsapp_sent_at text);CREATE TABLE card_stack_items(auction_date text,auction_name text,card_id text,card_image text,card_name text,card_number text,collection text,condition text,created_at timestamptz DEFAULT now(),finish text,id uuid PRIMARY KEY DEFAULT gen_random_uuid(),language text,order_id uuid,order_item_id uuid,picked_at text,picked_by text,quantity bigint,service_order_id uuid,stack_id uuid,status text,unit_price_cents bigint,updated_at timestamptz DEFAULT now(),user_id uuid);CREATE TABLE events(id uuid PRIMARY KEY,name text,active boolean,start_date date,end_date date,start_time time,end_time time,per_day_times jsonb);